  it('returns set autocomplete choices filtered by code or name', async () => {
    vi.stubGlobal(
      'fetch',
      vi.fn().mockResolvedValue(
        jsonResponse({
          data: [
            { code: 'mh3', name: 'Modern Horizons 3' },
            { code: 'lea', name: 'Limited Edition Alpha' },
          ],
        }),
      ),
    );
    const choices = await autocompleteSets('mh3');
    expect(choices).toEqual([{ name: 'Modern Horizons 3 (MH3)', value: 'MH3' }]);
  });

  it('sends Accept and User-Agent headers on scryfall requests', async () => {
    const fetchMock = vi.fn();
    fetchMock.mockResolvedValue(
      jsonResponse({ data: ['Test Card', 'Another Card'] }),
    );
    vi.stubGlobal('fetch', fetchMock);

    await autocompleteCards('test');

    expect(fetchMock).toHaveBeenCalled();
    const [url, init] = fetchMock.mock.calls[0] as [string, RequestInit | undefined];
    expect(url).toContain('api.scryfall.com');
    const headers = init?.headers as Record<string, string>;
    expect(headers?.Accept).toMatch(/^application\/json/);
    expect(headers?.['User-Agent']).toMatch(/^lfcbot\/\d+\.\d+\.\d+/);
  });
});

